const offsets = { ru: 0, ja: 1, de: 2, es: 3, fi: 4 };
export const driverTranslation = (language, key) => rows[key]?.[offsets[language]];
export const driverDictionary = language => Object.fromEntries(Object.entries(rows).map(([key, values]) => [key, values[offsets[language]]]));
